parameters.jsCode:
const t = $input.all()[0].json;
const now = new Date();
const slaDue = new Date(t.slaDueAt || t.dueAt);
const msToBreach = slaDue - now;
const hoursToBreach = msToBreach / 3600000;
const hoursOverdue = -hoursToBreach;

let stage = null;
if (hoursOverdue >= 24) stage = 'OVERDUE_24H';
else if (hoursOverdue >= 0) stage = 'BREACHED';
else if (hoursToBreach <= 2) stage = 'APPROACHING_BREACH';

if (!stage) return [{ json: { skip: true, reason: `SLA safe (${hoursToBreach.toFixed(1)}h to breach)` } }];

const escalationTier = {
  APPROACHING_BREACH: { notifyRoles: ['ASSIGNEE', 'MANAGER'], urgency: 'WARNING' },
  BREACHED: { notifyRoles: ['ASSIGNEE', 'MANAGER', 'SENIOR'], urgency: 'URGENT', markUrgent: true },
  OVERDUE_24H: { notifyRoles: ['ASSIGNEE', 'MANAGER', 'SENIOR', 'DIRECTOR'], urgency: 'CRITICAL' }
}[stage];

return [{
  json: {
    skip: false,
    stage,
    escalationTier,
    hoursToBreach: hoursToBreach.toFixed(2),
    hoursOverdue: hoursOverdue.toFixed(2),
    ticketId: t.id,
    ticketNumber: t.ticketNumber || t.id,
    subject: t.subject,
    priority: t.priority,
    category: t.category,
    assigneeId: t.assigneeId,
    tenantId: t.tenantId,
    customerId: t.customerId,
    slaDueAt: t.slaDueAt || t.dueAt
  }
}];

